source='''def transform(grid):
    """Slide the non-background object toward the straight color-2 wall.

    Mark the object's original bounding-box center with color 8, parallel to
    the wall. The wall remains unchanged.
    """
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Locate the straight wall.
    wall = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not wall:
        return out
    wall_rows = {r for r, c in wall}
    wall_cols = {c for r, c in wall}
    horizontal = len(wall_rows) == 1 and len(wall) == w
    vertical = len(wall_cols) == 1 and len(wall) == h
    if not (horizontal or vertical):
        return out

    bg = max(set(v for row in grid for v in row if v != 2),
             key=lambda v: sum(x == v for row in grid for x in row))
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (bg, 2)]
    if not pts:
        return out
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    color = grid[pts[0][0]][pts[0][1]]
    dr = dc = 0
    if vertical:
        wc = next(iter(wall_cols))
        if c1 < wc:
            dc = wc - 1 - c1
        elif c0 > wc:
            dc = wc + 1 - c0
        marker = (c0 + c1 + 1) // 2
        for r in range(h):
            if r not in wall_rows:
                out[r][marker] = 8
    else:
        wr = next(iter(wall_rows))
        if r1 < wr:
            dr = wr - 1 - r1
        elif r0 > wr:
            dr = wr + 1 - r0
        marker = (r0 + r1 + 1) // 2
        for c in range(w):
            if c not in wall_cols:
                out[marker][c] = 8
    # Clear the original object, then place it flush against the wall.
    for r, c in pts:
        out[r][c] = bg
    for r, c in pts:
        out[r + dr][c + dc] = color
    # Draw marker after moving the shape; wall pixels always stay color 2.
    if vertical:
        for r in range(h):
            if grid[r][marker] != 2:
                out[r][marker] = 8
    else:
        for c in range(w):
            if grid[marker][c] != 2:
                out[marker][c] = 8
    return out
